import React, { useState, useEffect } from "react";
import { startLiveBot } from "../services/api";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const LiveMeetingBot = () => {
  const [link, setLink] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [botJoined, setBotJoined] = useState(false);

  const navigate = useNavigate();

  /**
   * 🔹 Listen for "meeting-ended" event
   * This event is dispatched by the Chrome extension
   * when MediaRecorder stops.
   */
  useEffect(() => {
    const handleMeetingEnd = async (event) => {
      try {
        if (!event?.detail?.audio) {
          throw new Error("No audio received from recorder");
        }

        const audioBlob = event.detail.audio;

        const formData = new FormData();
        // ⚠️ backend expects "file"
        formData.append("file", audioBlob, "meeting.webm");

        const res = await axios.post(
          "http://localhost:5000/api/upload/audio",
          formData,
          {
            headers: {
              "Content-Type": "multipart/form-data",
            },
          }
        );

        // 🔹 Navigate to result page with AI output
        navigate("/result", { state: res.data });

      } catch (err) {
        console.error("❌ Meeting processing failed:", err);
        setError("Failed to analyze meeting");
      }
    };

    window.addEventListener("meeting-ended", handleMeetingEnd);

    return () => {
      window.removeEventListener("meeting-ended", handleMeetingEnd);
    };
  }, [navigate]);

  /**
   * 🔹 Start live meeting bot
   */
  const handleStartBot = async () => {
    const trimmedLink = link.trim();

    if (!trimmedLink.startsWith("http")) {
      setError("Please enter a valid meeting link");
      return;
    }

    setLoading(true);
    setError(null);
    setBotJoined(false);

    try {
      // ✅ send ONLY string
      await startLiveBot(trimmedLink);

      setBotJoined(true);
      setLink("");

      /**
       * 🔹 Notify Chrome Extension to start recording
       * content.js listens to window messages
       */
      window.postMessage({ type: "START_RECORDING" }, "*");

    } catch (err) {
      console.error(err);
      setError(err.response?.data?.error || "Failed to start bot");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="card">
      <h2>Live Meeting Bot</h2>

      <input
        type="text"
        placeholder="Enter Google Meet / Zoom link"
        value={link}
        onChange={(e) => setLink(e.target.value)}
        disabled={botJoined}
        style={{
          width: "100%",
          padding: "8px",
          marginBottom: "10px",
        }}
      />

      {error && <p style={{ color: "red" }}>{error}</p>}

      {botJoined && (
        <p style={{ color: "green", fontWeight: "bold" }}>
          🤖 Bot joined successfully. Recording in progress...
        </p>
      )}

      {!botJoined && (
        <button onClick={handleStartBot} disabled={loading}>
          {loading ? "Joining..." : "Join Meeting"}
        </button>
      )}
    </div>
  );
};

export default LiveMeetingBot;
